-- Тестовый СИНТЕТИЧЕСКИЙ датасет (вымышленный). Oracle.
-- Запускать в отдельной тестовой схеме.
-- =====================================================================

BEGIN EXECUTE IMMEDIATE 'DROP TABLE postupleniya CASCADE CONSTRAINTS'; EXCEPTION WHEN OTHERS THEN NULL; END;
/
BEGIN EXECUTE IMMEDIATE 'DROP TABLE nachisleniya CASCADE CONSTRAINTS'; EXCEPTION WHEN OTHERS THEN NULL; END;
/
BEGIN EXECUTE IMMEDIATE 'DROP TABLE excluded_kbk CASCADE CONSTRAINTS'; EXCEPTION WHEN OTHERS THEN NULL; END;
/
BEGIN EXECUTE IMMEDIATE 'DROP TABLE kbk_spr CASCADE CONSTRAINTS'; EXCEPTION WHEN OTHERS THEN NULL; END;
/
BEGIN EXECUTE IMMEDIATE 'DROP TABLE nalogoplatelshchiki CASCADE CONSTRAINTS'; EXCEPTION WHEN OTHERS THEN NULL; END;
/
BEGIN EXECUTE IMMEDIATE 'DROP TABLE regiony CASCADE CONSTRAINTS'; EXCEPTION WHEN OTHERS THEN NULL; END;
/

CREATE TABLE regiony (
  region_kod   NUMBER(2)     PRIMARY KEY,
  region_naim  VARCHAR2(100) NOT NULL,
  fed_okrug    VARCHAR2(20)  NOT NULL
);
CREATE TABLE nalogoplatelshchiki (
  inn          VARCHAR2(12)  PRIMARY KEY,
  naim         VARCHAR2(200) NOT NULL,
  region_kod   NUMBER(2)     NOT NULL,
  kategoriya   VARCHAR2(10),
  data_reg     DATE
);
CREATE TABLE kbk_spr (
  kbk           VARCHAR2(20)  PRIMARY KEY,
  kbk_naim      VARCHAR2(200) NOT NULL,
  priznak_nalog CHAR(1)       NOT NULL   -- 'Y' налоговый, 'N' неналоговый
);
CREATE TABLE excluded_kbk (
  kbk          VARCHAR2(20)               -- список исключений, ведётся вручную
);
CREATE TABLE nachisleniya (
  id        NUMBER       PRIMARY KEY,
  inn       VARCHAR2(12) NOT NULL,
  kbk       VARCHAR2(20) NOT NULL,
  period    VARCHAR2(6)  NOT NULL,        -- 'YYYYMM' (ТЕКСТ)
  summa     NUMBER(15,2),
  data_oper VARCHAR2(10)                  -- 'DD.MM.YYYY' (ТЕКСТ, не DATE!)
);
CREATE TABLE postupleniya (
  id        NUMBER       PRIMARY KEY,
  inn       VARCHAR2(12) NOT NULL,
  kbk       VARCHAR2(20) NOT NULL,
  period    VARCHAR2(6)  NOT NULL,
  summa     NUMBER(15,2),                 -- может быть NULL
  data_plat DATE                          -- нормальный DATE
);

